"use client";

import { cn } from "@/lib/utils";
import React, { useState, forwardRef } from "react";
import { CheckIcon, Pencil, Copy, X } from "lucide-react";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";

type EditableQuestionProps = {
  className?: string;
  title?: string;
  onUpdateTitle?: (newTitle: string) => void;
};

const EditableQuestion = forwardRef<HTMLDivElement, EditableQuestionProps>(({
  className,
  title: initialTitle,
  onUpdateTitle,
  ...props
}, ref) => {
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [title, setTitle] = useState(initialTitle || "");
  const [editingTitle, setEditingTitle] = useState("");

  const handleCopy = async () => {
    if (title) {
      try {
        await navigator.clipboard.writeText(title);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
      } catch (error) {
        console.error("Failed to copy to clipboard:", error);
      }
    }
  };

  const handleEdit = () => {
    setEditingTitle(title);
    setIsEditing(true);
  };

  const handleUpdate = () => {
    setIsEditing(false);
    setTitle(editingTitle);
    if (onUpdateTitle) onUpdateTitle(editingTitle);
  };

  const handleCancel = () => {
    setIsEditing(false);
    setEditingTitle("");
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && e.ctrlKey) {
      handleUpdate();
    } else if (e.key === "Escape") {
      handleCancel();
    }
  };

  return (
    <div ref={ref} className="flex group flex-col justify-end items-end mb-4 gap-y-2" {...props}>
      <div
        className={cn(
          "p-3 bg-neutral-200/40 max-w-lg overflow-hidden whitespace-pre-wrap break-words rounded-xl dark:border-neutral-200/20 border border-neutral-300/50 dark:bg-neutral-900 dark:text-gray-200 text-neutral-700",
          className
        )}
      >
        {isEditing ? (
          <div className="flex gap-2 items-center">
            <Textarea
              className="flex-1 bg-transparent border-b border-neutral-400 outline-none px-1 resize-none"
              value={editingTitle}
              onChange={(e) => setEditingTitle(e.target.value)}
              onKeyDown={handleKeyDown}
              autoFocus
              rows={2}
              placeholder="Saisissez votre question..."
            />
            <div className="flex flex-col gap-2">
              <Button
                variant="ghost"
                size="sm"
                className="rounded-full w-8 h-8 p-0"
                onClick={handleUpdate}
                title="Sauvegarder (Ctrl+Entrée)"
              >
                <CheckIcon size={16} />
              </Button>
              <Button
                variant="ghost"
                size="sm"
                className="rounded-full w-8 h-8 p-0"
                onClick={handleCancel}
                title="Annuler (Échap)"
              >
                <X size={16} />
              </Button>
            </div>
          </div>
        ) : (
          <span>{title}</span>
        )}
      </div>
      <div className="opacity-0 group-hover:opacity-100 w-full flex gap-4 justify-end items-center transition-opacity duration-200">
        {!isEditing && (
          <Button
            variant="ghost"
            size="sm"
            title="Modifier la question"
            className="bg-transparent dark:bg-transparent hover:bg-neutral-200/40 dark:hover:bg-neutral-500 rounded-full w-8 h-8 p-0"
            onClick={handleEdit}
          >
            <Pencil size={16} />
          </Button>
        )}

        <Button
          variant="ghost"
          size="sm"
          className="bg-transparent dark:bg-transparent hover:bg-neutral-200/40 dark:hover:bg-neutral-500 rounded-full w-8 h-8 p-0"
          onClick={handleCopy}
          title="Copier la question"
          disabled={!title}
        >
          {copied ? <CheckIcon size={16} /> : <Copy size={16} />}
        </Button>
      </div>
    </div>
  );
});

EditableQuestion.displayName = "EditableQuestion";

export default EditableQuestion;

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        destructive:
          "bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export const globalVariants = {
   variant: {
      default: "border bg-neutral-200/40 dark:bg-neutral-200/20 dark:hover:bg-neutral-200/40 text-black  dark:border-neutral-200/20  border-neutral-300/50 dark:text-neutral-200",
      ghost: "dark:hover:bg-neutral-700/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40 bg-neutral-200/40 hover:bg-neutral-300/60 dark:bg-neutral-700 dark:text-gray-200",
      outline: "border border-neutral-300/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40  dark:text-gray-200",
      none:"bg-none border-none",
    },
}
